int online_pages(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    struct mem_notify {
        int status;
        int nid;
    } notify;
    int node = pfn_to_nid(pfn);

    lock_memory_hotplug();

    notify.status = MEM_ONLINE;
    notify.nid = NUMA_NO_NODE;

    if (!node_online(node))
        notify.nid = node;

    ret = send_memory_notify(MEM_GOING_ONLINE, &notify, NULL);
    if (ret) {
        unlock_memory_hotplug();
        return ret;
    }

    if (!zone_is_populated())
        rebuild_zonelist();

    ret = __online_pages(pfn, nr_pages);
    if (!ret) {
        update_zone_statistics(pfn, nr_pages);
        if (should_rebuild_zonelist())
            rebuild_zonelist();

        send_memory_notify(MEM_ONLINE, &notify, NULL);
    }

    unlock_memory_hotplug();
    return ret;
}

int online_memory_range(unsigned long pfn, unsigned long nr_pages) {
    int result = 0;
    struct online_memory_notify {
        int action;
        int nid;
    } notify = {ACTION_ONLINE, -1};

    lock_hotplug();

    if (!node_online(pfn_to_nid(pfn))) {
        notify.nid = pfn_to_nid(pfn);
    }

    result = send_memory_notification(&notify);
    if (result < 0) {
        unlock_hotplug();
        return result;
    }

    if (zone_populated()) {
        rebuild_zonelists();
    }

    result = online_pages(pfn, nr_pages);
    if (result < 0) {
        unlock_hotplug();
        return result;
    }

    update_zone_statistics(pfn, nr_pages);

    if (zone_populated()) {
        rebuild_zonelists();
    }

    notify.action = ACTION_ONLINE_NOTIFY;
    send_memory_notification(&notify);

    unlock_hotplug();
    return result;
}

int online_pages(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    struct zone *zone;
    int nid;

    lock_memory_hotplug();

    nid = page_to_nid(pfn);
    if (!node_online(nid)) {
        ret = -EINVAL;
        goto unlock;
    }

    send_online_notification_begin(nid);
    if (ret < 0)
        goto unlock;

    zone = &NODE_DATA(nid)->node_zones[ZONE_NORMAL];
    if (!zone->present_pages) {
        rebuild_zonelist();
    }

    ret = online_page_range(pfn, nr_pages);
    if (ret < 0)
        goto unlock;

    update_zone_stat(zone);
    send_online_notification_end(nid);

unlock:
    unlock_memory_hotplug();
    return ret;
}

int online_pages_range(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    struct memory_notify notification;

    lock_memory_hotplug();

    if (!node_online(pfn_to_nid(pfn))) {
        notification.nid = pfn_to_nid(pfn);
    }

    notification.start = pfn;
    notification.end = pfn + nr_pages;
    notification.status_change = MEM_ONLINE;
    ret = send_memory_notify(MEM_GOING_ONLINE, &notification, NULL);
    if (ret) {
        unlock_memory_hotplug();
        return ret;
    }

    if (zone_populated()) {
        rebuild_zonelists();
    }

    ret = online_pages(pfn, nr_pages);
    if (ret < 0) {
        unlock_memory_hotplug();
        return ret;
    }

    update_zone_statistics();
    send_memory_notify(MEM_ONLINE, &notification, NULL);
    unlock_memory_hotplug();

    return 0;
}

#include <linux/mm.h>
#include <linux/memory.h>
#include <linux/notifier.h>

int online_memory_pages(unsigned long pfn, unsigned long nr_pages) {
    struct memory_notify arg;
    int ret = 0;

    lock_memory_hotplug();

    if (!node_online(pfn_to_nid(pfn))) {
        arg.nid = pfn_to_nid(pfn);
        arg.start = pfn;
        arg.end = pfn + nr_pages;
        ret = memory_notify(MEM_GOING_ONLINE, &arg);
        if (ret) {
            unlock_memory_hotplug();
            return ret;
        }
    }

    if (zone_spanned_pages(zone_for_pfn(pfn)) == 0) {
        rebuild_all_zonelists();
    }

    ret = __online_page_set_range_flags(pfn, nr_pages, online);
    if (ret < 0) {
        unlock_memory_hotplug();
        return ret;
    }

    arg.nid = pfn_to_nid(pfn);
    arg.start = pfn;
    arg.end = pfn + nr_pages;
    memory_notify(MEM_ONLINE, &arg);

    unlock_memory_hotplug();
    return 0;
}
